      var t=document.getElementById('apTasks').value.trim();
      if(!g){alert('Please add a focus');return}
      var out='Plan: '+g+'\nRhythm: '+(r==='weekly'?'Weekly':r==='biweekly'?'Every other week':'Monthly')+'\nTasks: '+(t||'—');
      var el=document.getElementById('apOut'); el.style.display='block'; el.textContent=out;
    });
    document.getElementById('apCopy').addEventListener('click',function(){
      var t=document.getElementById('apOut').textContent; if(!t) return; navigator.clipboard.writeText(t);
    });

    // Intake creator
    document.getElementById('iaBuild').addEventListener('click',function(){
      var a=document.getElementById('ia1').value.trim();
      var b=document.getElementById('ia2').value.trim();
      var c=document.getElementById('ia3').value.trim();
      var lines=[];
      lines.push('Intake prompts:');
