      if(b) lines.push('- Impact: '+b);
      if(c) lines.push('- Aim: '+c);
      lines.push('Bring examples of when the problem shows up and a recent situation that captures the issue.');
      var out=document.getElementById('iaOut'); out.style.display='block'; out.textContent=lines.join('\n');
    });
